+    border-color: #2563eb;
+}
+
+.btn-page:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+
+/* States */
+.catalog-loading,
+.catalog-empty,
+.catalog-error {
+    text-align: center;
+    padding: 3rem 1rem;
+    color: #6b7280;
+}
+
+.catalog-error {
+    color: #dc2626;
+}
+
+.catalog-error button {
+    margin-top: 1rem;
+    padding: 0.5rem 1.5rem;
+    background: #2563eb;
+    color: white;
+    border: none;
+    border-radius: 4px;
+    cursor: pointer;
+}
